// Restore the supplied legacy strip's scroll owner with Chromium155 controls.
// Width-policy and preferred-size observation follow the former Chromium
// TabStripScrollContainer; keep the existing default strip implementation.
class TabStripScrollContainer final : public views::View,
                                      public views::ViewObserver {
  METADATA_HEADER(TabStripScrollContainer, views::View)

 public:
  TabStripScrollContainer(BrowserView* browser_view,
                          std::unique_ptr<TabStrip> tab_strip)
      : tab_strip_(tab_strip.get()), profile_(browser_view->GetProfile()) {
    tab_strip_observation_.Observe(tab_strip_);
    scroll_view_ = AddChildView(std::make_unique<views::ScrollView>(
        views::ScrollView::ScrollWithLayers::kEnabled));
    scroll_view_->SetBackgroundColor(std::nullopt);
    scroll_view_->SetUseContentsPreferredSize(true);
    scroll_view_->SetHorizontalScrollBarMode(
        views::ScrollView::ScrollBarMode::kHiddenButEnabled);
    scroll_view_->SetVerticalScrollBarMode(
        views::ScrollView::ScrollBarMode::kDisabled);
    scroll_view_->SetTreatAllScrollEventsAsHorizontal(true);
    scroll_view_->SetCustomOverflowIndicator(
        views::OverflowIndicatorAlignment::kLeft,
        std::make_unique<HorizontalTabStripOverflowIndicatorView>(
            views::OverflowIndicatorAlignment::kLeft),
        HorizontalTabStripOverflowIndicatorView::kTotalThickness, false);
    scroll_view_->SetCustomOverflowIndicator(
        views::OverflowIndicatorAlignment::kRight,
        std::make_unique<HorizontalTabStripOverflowIndicatorView>(
            views::OverflowIndicatorAlignment::kRight),
        HorizontalTabStripOverflowIndicatorView::kTotalThickness, false);
    scroll_view_->SetContents(std::move(tab_strip));
    scroll_buttons_ = AddChildView(std::make_unique<TabScrollButtonContainer>(
        browser_view->browser()));
    scroll_buttons_->SetScrollView(scroll_view_);
    scroll_buttons_->SetVisible(false);
    tab_strip_->SetAvailableWidthCallback(base::BindRepeating(
        &TabStripScrollContainer::GetTabStripAvailableWidth,
        base::Unretained(this)));
    scrolled_subscription_ = scroll_view_->AddContentsScrolledCallback(
        base::BindRepeating(&TabStripScrollContainer::OnContentsScrolled,
                            base::Unretained(this)));
    local_state_registrar_.Init(g_browser_process->local_state());
    local_state_registrar_.Add(
        tabs::kAuxHorizontalTabShrinkEnabled,
        base::BindRepeating(&TabStripScrollContainer::OnShrinkChanged,
                            base::Unretained(this)));
    profile_registrar_.Init(profile_->GetPrefs());
    profile_registrar_.Add(
        prefs::kTabScrollButtonsPinnedToTabstrip,
        base::BindRepeating(&TabStripScrollContainer::InvalidateLayout,
                            base::Unretained(this), false));
  }

  ~TabStripScrollContainer() override {
    scroll_buttons_->SetScrollView(nullptr);
  }

  void OnViewPreferredSizeChanged(views::View* view) override {
    CHECK_EQ(view, tab_strip_);
    PreferredSizeChanged();
    InvalidateLayout();
  }

  gfx::Size CalculatePreferredSize(
      const views::SizeBounds& available_size) const override {
    return tab_strip_->GetPreferredSize(available_size);
  }

  gfx::Size GetMinimumSize() const override {
    return gfx::Size(0, tab_strip_->GetMinimumSize().height());
  }

  bool IsRectInWindowCaption(const gfx::Rect& rect) {
    const auto target_rect = [&](views::View* target) {
      return gfx::ToEnclosingRect(views::View::ConvertRectToTarget(
          this, target, gfx::RectF(rect)));
    };
    if (scroll_buttons_->GetVisible() &&
        scroll_buttons_->bounds().Intersects(rect)) {
      return scroll_buttons_->IsPositionInWindowCaption(
          target_rect(scroll_buttons_).origin());
    }
    if (scroll_view_->bounds().Intersects(rect)) {
      return tab_strip_->IsRectInWindowCaption(target_rect(tab_strip_));
    }
    return true;
  }

  void Layout(PassKey) override {
    const int minimum_content_width = ShrinkEnabled()
        ? tab_strip_->GetMinimumSize().width()
        : tab_strip_->GetPreferredSize({}).width();
    const bool show_buttons = minimum_content_width > width() &&
        profile_->GetPrefs()->GetBoolean(prefs::kTabScrollButtonsPinnedToTabstrip);
    scroll_buttons_->SetVisible(show_buttons);
    const int button_width = show_buttons
        ? std::min(width(), scroll_buttons_->GetPreferredSize().width()) : 0;
    scroll_view_->SetBounds(0, 0, std::max(0, width() - button_width), height());
    scroll_buttons_->SetBounds(width() - button_width, 0, button_width, height());
    scroll_view_->SetDrawOverflowIndicator(
        minimum_content_width > scroll_view_->width());
    scroll_view_->DeprecatedLayoutImmediately();
  }

 private:
  bool ShrinkEnabled() const {
    return g_browser_process->local_state()->GetBoolean(
        tabs::kAuxHorizontalTabShrinkEnabled);
  }

  int GetTabStripAvailableWidth() const {
    return ShrinkEnabled() ? scroll_view_->width()
                           : tab_strip_->GetPreferredSize({}).width();
  }

  void OnShrinkChanged() {
    tab_strip_->InvalidateLayout();
    tab_strip_->PreferredSizeChanged();
    PreferredSizeChanged();
    InvalidateLayout();
  }

  void OnContentsScrolled() {
    tab_strip_->UpdateHoverCard(nullptr,
        TabSlotController::HoverCardUpdateType::kAnimating);
  }

  const raw_ptr<TabStrip> tab_strip_;
  const raw_ptr<Profile> profile_;
  raw_ptr<views::ScrollView> scroll_view_ = nullptr;
  raw_ptr<TabScrollButtonContainer> scroll_buttons_ = nullptr;
  base::ScopedObservation<views::View, views::ViewObserver>
      tab_strip_observation_{this};
  PrefChangeRegistrar local_state_registrar_;
  PrefChangeRegistrar profile_registrar_;
  base::CallbackListSubscription scrolled_subscription_;
};

